// Bundle spec/i18n/*.json into src/i18n-data.ts so the library needs no files at runtime.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "..", "spec", "i18n");
const out = {};
for (const f of readdirSync(dir).filter((f) => f.endsWith(".json")).sort()) {
  out[f.slice(0, -5)] = JSON.parse(readFileSync(join(dir, f), "utf8"));
}
const src =
  "// GENERATED by scripts/gen-i18n.mjs from spec/i18n/*.json. Do not edit.\n" +
  'import type { Language } from "./render.js";\n\n' +
  "export const LANGUAGES: Record<string, Language> = " +
  JSON.stringify(out, null, 1) +
  ";\n";
writeFileSync(join(root, "src", "i18n-data.ts"), src);
console.log("wrote src/i18n-data.ts:", Object.keys(out).join(", "));
